/**
 * Helper function to get worst predictions (largest absolute errors)
 * @param {Array} errors - Array of error objects from backtestAccuracy
 * @param {number} count - Number of worst predictions to return (default 5)
 * @returns {Array} Top N worst predictions sorted by absolute error descending
 */
export function getWorstPredictions(errors, count = 5) {
  if (!Array.isArray(errors) || errors.length === 0) {
    return [];
  }
  return [...errors]
    .sort((a, b) => b.absError - a.absError)
    .slice(0, count);
}

/**
 * Backtest model accuracy by comparing historical predictions against actual block intervals
 * 
 * Simulates real-time predictions by iterating through blocks chronologically, using only
 * prior blocks to compute empirical lambda for each prediction. This avoids lookahead bias
 * and provides a realistic assessment of model performance.
 * 
 * Mathematical formulas:
 * - Predicted median: median = ln(2)/λ
 * - Mean Absolute Error: MAE = (1/n)Σ|eᵢ|
 * - Root Mean Square Error: RMSE = sqrt((1/n)Σeᵢ²)
 * - Calibration: (count(actualᵢ < predictedᵢ) / n) * 100
 * 
 * For a well-calibrated exponential distribution, calibration should be approximately 50%,
 * meaning about half of actual intervals are below the predicted median.
 * 
 * @param {PoolBlock[]} filteredBlocks - Array of blocks (outliers removed), sorted by timestamp descending
 * @param {Function} lambdaFunc - Function `(priorBlocks) => lambda` that computes empirical lambda from prior blocks only
 * @returns {{
 *   metrics: {
 *     mae: number,              // Mean Absolute Error in seconds
 *     rmse: number,            // Root Mean Square Error in seconds
 *     calibration: number,      // Percentage of actuals < predicted median (0-100)
 *     totalPredictions: number, // Number of successful predictions
 *     meanError: number        // Average signed error (bias indicator) in seconds
 *   },
 *   errors: Array<{
 *     blockHeight: number,
 *     blockTimestamp: number,
 *     actualInterval: number,
 *     predictedMedian: number,
 *     error: number,
 *     percentError: number,
 *     absError: number
 *   }>,
 *   summary: {
 *     bestPrediction: Object | null,
 *     worstPrediction: Object | null,
 *     medianError: number
 *   }
 * } | null} Backtesting results, or null if insufficient data
 * 
 * @example
 * // Define lambda function that computes empirical lambda from prior blocks
 * const lambdaFunc = (priorBlocks) => {
 *   if (priorBlocks.length < 2) return null;
 *   const empiricalStats = calculateEmpiricalLambda(priorBlocks);
 *   return empiricalStats?.lambda || null;
 * };
 * 
 * const results = backtestAccuracy(filteredBlocks, lambdaFunc);
 * console.log('MAE:', results.metrics.mae);
 * console.log('RMSE:', results.metrics.rmse);
 * console.log('Calibration:', results.metrics.calibration + '%');
 */
export function backtestAccuracy(filteredBlocks, lambdaFunc) {
  // Input validation
  if (!Array.isArray(filteredBlocks) || filteredBlocks.length < 2) {
    if (DEBUG_POISSON) {
      console.warn('Insufficient blocks for backtesting:', filteredBlocks.length);
    }
    return null;
  }
  
  if (typeof lambdaFunc !== 'function') {
    throw new Error('lambdaFunc must be a function');
  }
  
  // Sort blocks chronologically (oldest first) for forward iteration
  const sortedBlocks = [...filteredBlocks].sort((a, b) => a.timestamp - b.timestamp);
  
  // Validate timestamps are monotonically increasing
  for (let i = 1; i < sortedBlocks.length; i++) {
    if (sortedBlocks[i].timestamp <= sortedBlocks[i - 1].timestamp) {
      if (DEBUG_POISSON) {
        console.warn('Non-monotonic timestamps detected, skipping backtesting');
      }
      return null;
    }
  }
  
  const errors = [];
  
  // For each block i (starting from index 1, since block 0 has no prior interval)
  for (let i = 1; i < sortedBlocks.length; i++) {
    // Extract prior blocks (all blocks before current)
    const priorBlocks = sortedBlocks.slice(0, i);
    
    // Compute lambda from prior blocks only (no lookahead bias)
    let lambdaPredicted = null;
    try {
      lambdaPredicted = lambdaFunc(priorBlocks);
    } catch (err) {
      if (DEBUG_POISSON) {
        console.warn(`Lambda function failed for block ${sortedBlocks[i].height}:`, err);
      }
      continue; // Skip this prediction
    }
    
    // Validate lambda
    if (!Number.isFinite(lambdaPredicted) || lambdaPredicted <= 0) {
      if (DEBUG_POISSON) {
        console.warn(`Invalid lambda for block ${sortedBlocks[i].height}:`, lambdaPredicted);
      }
      continue; // Skip this prediction
    }
    
    // Calculate predicted median: median = ln(2)/λ
    const predictedMedian = exponentialMedian(lambdaPredicted);
    
    // Compute actual interval
    const actualInterval = sortedBlocks[i].timestamp - sortedBlocks[i - 1].timestamp;
    
    // Validate actual interval
    if (!Number.isFinite(actualInterval) || actualInterval <= 0) {
      if (DEBUG_POISSON) {
        console.warn(`Invalid actual interval for block ${sortedBlocks[i].height}:`, actualInterval);
      }
      continue; // Skip this prediction
    }
    
    // Calculate error: actual - predicted (positive = underestimated, negative = overestimated)
    const error = actualInterval - predictedMedian;
    
    // Calculate percent error
    const percentError = (error / actualInterval) * 100;
    
    // Store per-block result
    errors.push({
      blockHeight: sortedBlocks[i].height,
      blockTimestamp: sortedBlocks[i].timestamp,
      actualInterval,
      predictedMedian,
      error,
      percentError,
      absError: Math.abs(error),
    });
  }
  
  // Handle case where no valid predictions were made
  if (errors.length === 0) {
    if (DEBUG_POISSON) {
      console.warn('No valid predictions made during backtesting');
    }
    return null;
  }
  
  // Compute aggregate metrics
  const errorValues = errors.map(e => e.error);
  const absErrorValues = errors.map(e => e.absError);
  
  // Mean Absolute Error: MAE = (1/n)Σ|eᵢ|
  const mae = absErrorValues.reduce((sum, err) => sum + err, 0) / absErrorValues.length;
  
  // Root Mean Square Error: RMSE = sqrt((1/n)Σeᵢ²)
  const squaredErrors = errorValues.map(e => e * e);
  const meanSquaredError = squaredErrors.reduce((sum, sqErr) => sum + sqErr, 0) / squaredErrors.length;
  const rmse = Math.sqrt(meanSquaredError);
  
  // Mean signed error (bias indicator)
  const meanError = errorValues.reduce((sum, err) => sum + err, 0) / errorValues.length;
  
  // Calibration: percentage of actual intervals < predicted median
  // For well-calibrated exponential model, should be ~50%
  const belowMedianCount = errors.filter(e => e.actualInterval < e.predictedMedian).length;
  const calibration = (belowMedianCount / errors.length) * 100;
  
  // Find best and worst predictions
  const bestPrediction = errors.reduce((best, current) => 
    current.absError < best.absError ? current : best, errors[0]);
  const worstPrediction = errors.reduce((worst, current) => 
    current.absError > worst.absError ? current : worst, errors[0]);
  
  // Calculate median error
  const sortedAbsErrors = [...absErrorValues].sort((a, b) => a - b);
  const medianError = sortedAbsErrors.length % 2 === 0
    ? (sortedAbsErrors[sortedAbsErrors.length / 2 - 1] + sortedAbsErrors[sortedAbsErrors.length / 2]) / 2
    : sortedAbsErrors[Math.floor(sortedAbsErrors.length / 2)];
  
  const result = {
    metrics: {
      mae,
      rmse,
      calibration,
      totalPredictions: errors.length,
      meanError,
    },
    errors,
    summary: {
      bestPrediction,
      worstPrediction,
      medianError,
    },
  };
  
  if (DEBUG_POISSON) {
    console.log('Backtesting results:', {
      mae: result.metrics.mae,
      rmse: result.metrics.rmse,
      calibration: result.metrics.calibration,
      totalPredictions: result.metrics.totalPredictions,
      errorsCount: result.errors.length,
    });
  }
  
  return result;
}

/**
 * Optimize model parameters via grid search to minimize backtest MAE
 * 
 * Performs grid search over candidate parameter combinations (outlierPThreshold × hashrateWeight)
 * to find the parameter set that minimizes Mean Absolute Error (MAE) from backtesting.
 * 
 * Mathematical approach:
 * - Tests all combinations of outlierPThreshold × hashrateWeight
 * - For each combination:
 *   1. Runs outlier detection with given pThreshold
 *   2. Filters outliers from blocks
 *   3. Backtests predictions using empirical lambda
 *   4. Computes MAE = (1/n)Σ|actual_i - predicted_i|
 * - Returns parameter set with lowest MAE
 * 
 * @param {PoolBlock[]} blocks - Array of raw blocks before outlier filtering
 * @param {PoolInfo} poolInfo - Pool information for lambda calculation
 * @param {Object} candidateParams - Grid search space:
 *   - {number[]} outlierPThresholds - Array of p-threshold values (e.g., [0.01, 0.02, ..., 0.1])
 *   - {number[]} hashrateWeights - Array of hashrate weight values (e.g., [0, 0.1, ..., 1.0])
 * @param {Object} [options] - Optional configuration:
 *   - {number} maxIterations - Max outlier detection iterations (default 3)
 *   - {Function} progressCallback - Called with (current, total, bestSoFar) for progress updates
 * @returns {{
 *   bestParams: { outlierPThreshold: number, hashrateWeight: number },
 *   bestMAE: number,
 *   allResults: Array<{
 *     pThreshold: number,
 *     hashrateWeight: number,
 *     mae: number,
 *     rmse: number,
 *     calibration: number,
 *     outliersCount: number
 *   }>,
 *   totalCombinations: number
 * } | null} Optimization results, or null if insufficient data or all combinations fail
 * 
 * @example
 * const candidateParams = {
 *   outlierPThresholds: [0.01, 0.03, 0.05, 0.07, 0.1],
 *   hashrateWeights: [0.3, 0.4, 0.5, 0.6, 0.7],
 * };
 * 
 * const result = optimizeModelParams(blocks, poolInfo, candidateParams, {
 *   maxIterations: 3,
 *   progressCallback: (current, total, bestMAE) => {
 *     console.log(`Progress: ${current}/${total}, best MAE: ${bestMAE?.toFixed(2)}s`);
 *   },
 * });
 * 
 * if (result) {
 *   console.log('Optimal parameters:', result.bestParams);
 *   console.log('Best MAE:', result.bestMAE, 'seconds');
 * }
 */
export function optimizeModelParams(blocks, poolInfo, candidateParams, options = {}) {
  // Input validation
  if (!Array.isArray(blocks) || blocks.length < 10) {
    if (DEBUG_POISSON) {
      console.warn('Insufficient blocks for optimization:', blocks.length);
    }
    return null;
  }
  
  if (!poolInfo) {
    throw new Error('Pool info is required for optimization');
  }
  
  if (!candidateParams || !Array.isArray(candidateParams.outlierPThresholds) || 
      candidateParams.outlierPThresholds.length === 0 ||
      !Array.isArray(candidateParams.hashrateWeights) || 
      candidateParams.hashrateWeights.length === 0) {
    throw new Error('candidateParams must contain non-empty outlierPThresholds and hashrateWeights arrays');
  }
  
  const { maxIterations = 3, progressCallback } = options;
  
  // Initialize tracking variables
  let bestParams = null;
  let bestMAE = Infinity;
  const results = [];
  const totalCombinations = candidateParams.outlierPThresholds.length * candidateParams.hashrateWeights.length;
  let currentCombination = 0;
  
  // Nested loop over all parameter combinations
  for (const pThreshold of candidateParams.outlierPThresholds) {
    for (const hashrateWeight of candidateParams.hashrateWeights) {
      currentCombination++;
      
      try {
        // Compute initial lambda using current hashrateWeight
        const blockShareWeight = 1 - hashrateWeight;
        const initialLambda = calculatePoolBlockRateFromPoolInfo(poolInfo, hashrateWeight, blockShareWeight);
        
        // Skip if initialLambda is invalid
        if (initialLambda <= 0 || !Number.isFinite(initialLambda)) {
          if (DEBUG_POISSON) {
            console.warn(`Skipping combination (pThreshold=${pThreshold}, hashrateWeight=${hashrateWeight}): invalid lambda`);
          }
          continue;
        }
        
        // Run outlier detection with current pThreshold
        const outlierResult = detectOutliers(blocks, initialLambda, pThreshold, maxIterations);
        const filteredBlocks = outlierResult.blocks.filter(b => !b.isOutlier);
        
        // Skip if insufficient filtered blocks
        if (filteredBlocks.length < 2) {
          if (DEBUG_POISSON) {
            console.warn(`Skipping combination (pThreshold=${pThreshold}, hashrateWeight=${hashrateWeight}): insufficient filtered blocks (${filteredBlocks.length})`);
          }
          continue;
        }
        
        // Define lambda function for backtesting (uses empirical lambda from prior blocks)
        const lambdaFunc = (priorBlocks) => {
          if (priorBlocks.length < 2) return null;
          const empiricalStats = calculateEmpiricalLambda(priorBlocks);
          return empiricalStats?.lambda || null;
        };
        
        // Run backtesting
        const backtestResult = backtestAccuracy(filteredBlocks, lambdaFunc);
        
        // Skip if backtesting failed
        if (!backtestResult) {
          if (DEBUG_POISSON) {
            console.warn(`Skipping combination (pThreshold=${pThreshold}, hashrateWeight=${hashrateWeight}): backtesting failed`);
          }
          continue;
        }
        
        // Extract metrics
        const mae = backtestResult.metrics.mae;
        const rmse = backtestResult.metrics.rmse;
        const calibration = backtestResult.metrics.calibration;
        const outliersCount = outlierResult.outliersCount;
        
        // Store result
        results.push({
          pThreshold,
          hashrateWeight,
          mae,
          rmse,
          calibration,
          outliersCount,
        });
        
        // Update best if this combination has lower MAE
        if (mae < bestMAE) {
          bestMAE = mae;
          bestParams = {
            outlierPThreshold: pThreshold,
            hashrateWeight,
          };
        }
        
        // Call progress callback if provided
        if (progressCallback) {
          progressCallback(currentCombination, totalCombinations, bestMAE);
        }
      } catch (err) {
        if (DEBUG_POISSON) {
          console.warn(`Error in optimization combination (pThreshold=${pThreshold}, hashrateWeight=${hashrateWeight}):`, err);
        }
        // Continue to next combination on error
        continue;
      }
    }
  }
  
  // Return null if no valid results
  if (results.length === 0) {
    if (DEBUG_POISSON) {
      console.warn('Optimization failed: no valid parameter combinations found');
    }
    return null;
  }
  
  // Sort results by MAE ascending
  results.sort((a, b) => a.mae - b.mae);
  
  return {
    bestParams,
    bestMAE,
    allResults: results,
    totalCombinations: results.length,
  };
}

